module.exports = {
  plugins: [
    require('postcss-import'),
    require('postcss-nesting'),
    require('autoprefixer'),
    process.env.NODE_ENV === 'production' ? require('cssnano')({ preset: 'default' }) : null,
  ].filter(Boolean),
}

@layer primitives;

/* Цвета — примитивы (OKLCH) */
:root {
  /* Серые оттенки */
  --primitive-color-slate-50: oklch(0.98 0.001 285);
  --primitive-color-slate-100: oklch(0.96 0.003 285);
  --primitive-color-slate-200: oklch(0.92 0.006 285);
  --primitive-color-slate-300: oklch(0.87 0.008 285);
  --primitive-color-slate-400: oklch(0.70 0.01 285);
  --primitive-color-slate-500: oklch(0.55 0.01 285);
  --primitive-color-slate-600: oklch(0.45 0.01 285);
  --primitive-color-slate-700: oklch(0.32 0.006 285);
  --primitive-color-slate-800: oklch(0.24 0.006 285);
  --primitive-color-slate-900: oklch(0.21 0.006 285);
  --primitive-color-slate-950: oklch(0.12 0.003 285);

  /* Основные цвета */
  --primitive-color-blue-50: oklch(0.96 0.03 264);
  --primitive-color-blue-100: oklch(0.92 0.06 264);
  --primitive-color-blue-500: oklch(0.62 0.22 264);
  --primitive-color-blue-600: oklch(0.55 0.22 264);
  --primitive-color-blue-700: oklch(0.48 0.20 264);

  --primitive-color-green-50: oklch(0.97 0.02 150);
  --primitive-color-green-100: oklch(0.94 0.04 150);
  --primitive-color-green-500: oklch(0.75 0.18 150);
  --primitive-color-green-600: oklch(0.68 0.18 150);

  --primitive-color-red-50: oklch(0.97 0.01 20);
  --primitive-color-red-100: oklch(0.94 0.02 20);
  --primitive-color-red-500: oklch(0.65 0.22 20);
  --primitive-color-red-600: oklch(0.58 0.22 20);

  /* Отступы */
  --primitive-space-0: 0;
  --primitive-space-xs: 0.25rem;
  --primitive-space-sm: 0.5rem;
  --primitive-space-md: 1rem;
  --primitive-space-lg: 1.5rem;
  --primitive-space-xl: 2rem;
  --primitive-space-2xl: 3rem;
  --primitive-space-3xl: 4rem;

  /* Размеры шрифтов */
  --primitive-fs-xs: 0.75rem;
  --primitive-fs-sm: 0.875rem;
  --primitive-fs-base: 1rem;
  --primitive-fs-lg: 1.125rem;
  --primitive-fs-xl: 1.25rem;
  --primitive-fs-2xl: 1.5rem;
  --primitive-fs-3xl: 2rem;
  --primitive-fs-4xl: 2.5rem;

  /* Радиусы */
  --primitive-radius-sm: 0.25rem;
  --primitive-radius-md: 0.5rem;
  --primitive-radius-lg: 1rem;
  --primitive-radius-xl: 1.5rem;
  --primitive-radius-full: 9999px;

  /* Тени */
  --primitive-shadow-xs: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --primitive-shadow-sm: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px -1px rgb(0 0 0 / 0.1);
  --primitive-shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --primitive-shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);

  /* Длительности анимации */
  --primitive-duration-fast: 150ms;
  --primitive-duration-base: 250ms;
  --primitive-duration-slow: 350ms;

  /* Функции easing */
  --primitive-ease-base: cubic-bezier(0.4, 0, 0.2, 1);
  --primitive-ease-in: cubic-bezier(0.4, 0, 1, 1);
  --primitive-ease-out: cubic-bezier(0, 0, 0.2, 1);
  --primitive-ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
}

@layer semantic;

/* Семантические цвета */
:root {
  --color-bg: var(--primitive-color-slate-50);
  --color-bg-inverted: var(--primitive-color-slate-950);
  --color-surface: white;
  --color-surface-inverted: var(--primitive-color-slate-900);

  --color-text: var(--primitive-color-slate-900);
  --color-text-inverted: var(--primitive-color-slate-50);
  --color-text-secondary: var(--primitive-color-slate-600);
  --color-text-muted: var(--primitive-color-slate-500);

  --color-border: var(--primitive-color-slate-200);
  --color-border-hover: var(--primitive-color-slate-300);
  --color-border-focused: var(--primitive-color-blue-500);

  --color-primary: var(--primitive-color-blue-600);
  --color-primary-hover: var(--primitive-color-blue-500);
  --color-primary-active: var(--primitive-color-blue-700);
  --color-primary-subtle: color-mix(in oklch, var(--primitive-color-blue-600), white 92%);

  --color-success: var(--primitive-color-green-500);
  --color-success-subtle: color-mix(in oklch, var(--primitive-color-green-500), white 92%);

  --color-error: var(--primitive-color-red-500);
  --color-error-subtle: color-mix(in oklch, var(--primitive-color-red-500), white 92%);

  --color-warning: oklch(0.80 0.15 60);
  --color-warning-subtle: color-mix(in oklch, oklch(0.80 0.15 60), white 92%);

  /* Семантические отступы */
  --space-xs: var(--primitive-space-xs);
  --space-sm: var(--primitive-space-sm);
  --space-md: var(--primitive-space-md);
  --space-lg: var(--primitive-space-lg);
  --space-xl: var(--primitive-space-xl);
  --space-2xl: var(--primitive-space-2xl);
  --space-3xl: var(--primitive-space-3xl);

  /* Семантические размеры шрифтов */
  --fs-xs: var(--primitive-fs-xs);
  --fs-sm: var(--primitive-fs-sm);
  --fs-base: var(--primitive-fs-base);
  --fs-lg: var(--primitive-fs-lg);
  --fs-xl: var(--primitive-fs-xl);
  --fs-2xl: var(--primitive-fs-2xl);
  --fs-3xl: var(--primitive-fs-3xl);
  --fs-4xl: var(--primitive-fs-4xl);

  /* Семантические радиусы */
  --radius-sm: var(--primitive-radius-sm);
  --radius-md: var(--primitive-radius-md);
  --radius-lg: var(--primitive-radius-lg);
  --radius-xl: var(--primitive-radius-xl);
  --radius-full: var(--primitive-radius-full);

  /* Семантические тени */
  --shadow-xs: var(--primitive-shadow-xs);
  --shadow-sm: var(--primitive-shadow-sm);
  --shadow-md: var(--primitive-shadow-md);
  --shadow-lg: var(--primitive-shadow-lg);

  /* Семантические длительности */
  --duration-fast: var(--primitive-duration-fast);
  --duration-base: var(--primitive-duration-base);
  --duration-slow: var(--primitive-duration-slow);

  /* Семантические easing */
  --ease-base: var(--primitive-ease-base);
  --ease-in: var(--primitive-ease-in);
  --ease-out: var(--primitive-ease-out);
  --ease-in-out: var(--primitive-ease-in-out);

  /* Семантические line-height */
  --line-height-tight: 1.25;
  --line-height-base: 1.6;
  --line-height-relaxed: 1.75;
}

@layer components-tokens;

/* Компонентные токены — кнопка */
:root {
  --btn-height-sm: 32px;
  --btn-height-md: 40px;
  --btn-height-lg: 48px;
  --btn-padding-sm: var(--space-xs) var(--space-sm);
  --btn-padding-md: var(--space-sm) var(--space-md);
  --btn-padding-lg: var(--space-md) var(--space-lg);
  --btn-font-size-sm: var(--fs-xs);
  --btn-font-size-md: var(--fs-sm);
  --btn-font-size-lg: var(--fs-base);
  --btn-radius: var(--radius-md);
  --btn-font-weight: 600;
}

/* Компонентные токены — карточка */
:root {
  --card-padding: var(--space-lg);
  --card-radius: var(--radius-lg);
  --card-border: 1px solid var(--color-border);
  --card-shadow: var(--shadow-md);
  --card-gap: var(--space-md);
}

/* Компонентные токены — модалка */
:root {
  --modal-max-width: 560px;
  --modal-padding: var(--space-xl);
  --modal-radius: var(--radius-lg);
  --modal-shadow: var(--shadow-lg);
  --modal-backdrop: rgb(0 0 0 / 0.5);
}

/* Компонентные токены — навигация */
:root {
  --nav-height: 64px;
  --nav-item-padding: var(--space-xs) 0;
  --nav-gap: var(--space-md);
}

/* Компонентные токены — инпут */
:root {
  --input-height: 40px;
  --input-padding: var(--space-sm) var(--space-md);
  --input-radius: var(--radius-md);
  --input-border: 1px solid var(--color-border);
  --input-border-focused: 2px solid var(--color-primary);
}

@layer themes;

[data-theme="light"] {
  --color-bg: var(--primitive-color-slate-50);
  --color-bg-inverted: var(--primitive-color-slate-950);
  --color-surface: white;
  --color-surface-inverted: var(--primitive-color-slate-900);

  --color-text: var(--primitive-color-slate-900);
  --color-text-inverted: var(--primitive-color-slate-50);
  --color-text-secondary: var(--primitive-color-slate-600);
  --color-text-muted: var(--primitive-color-slate-500);

  --color-border: var(--primitive-color-slate-200);
  --color-border-hover: var(--primitive-color-slate-300);

  /* Автоматически подтягиваются из semantic.css */
}

[data-theme="dark"] {
  --color-bg: var(--primitive-color-slate-950);
  --color-bg-inverted: var(--primitive-color-slate-50);
  --color-surface: var(--primitive-color-slate-900);
  --color-surface-inverted: var(--primitive-color-slate-50);

  --color-text: var(--primitive-color-slate-50);
  --color-text-inverted: var(--primitive-color-slate-950);
  --color-text-secondary: var(--primitive-color-slate-400);
  --color-text-muted: var(--primitive-color-slate-500);

  --color-border: var(--primitive-color-slate-800);
  --color-border-hover: var(--primitive-color-slate-700);

  /* Тени темнее в темной теме */
  --shadow-sm: 0 1px 3px 0 rgb(0 0 0 / 0.3);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.4);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.5);
}

[data-brand="brand-a"] {
  --color-primary: var(--primitive-color-blue-600);
  --color-primary-hover: var(--primitive-color-blue-500);
  --color-primary-active: var(--primitive-color-blue-700);
  --color-success: var(--primitive-color-green-500);
  --color-error: var(--primitive-color-red-500);
  --font-family: 'Inter', system-ui, -apple-system, sans-serif;
}

[data-brand="brand-b"] {
  --color-primary: oklch(0.65 0.18 150);
  --color-primary-hover: oklch(0.58 0.18 150);
  --color-primary-active: oklch(0.50 0.18 150);
  --color-success: oklch(0.70 0.15 140);
  --color-error: oklch(0.60 0.20 25);
  --font-family: 'Roboto', system-ui, -apple-system, sans-serif;
}

@layer components;

/* Базовые стили кнопки */
.c-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-xs);
  min-height: var(--btn-height-md);
  padding: var(--btn-padding-md);
  font-size: var(--btn-font-size-md);
  font-weight: var(--btn-font-weight);
  font-family: var(--font-family, inherit);
  border: none;
  border-radius: var(--btn-radius);
  cursor: pointer;
  background: transparent;
  color: var(--color-text);
  transition:
    background var(--duration-base) var(--ease-base),
    border-color var(--duration-base) var(--ease-base),
    color var(--duration-base) var(--ease-base),
    transform var(--duration-fast) var(--ease-base);
  contain: paint;
}

/• Варианты */
.c-btn--primary {
  background: var(--color-primary);
  color: var(--color-text-inverted);
}

.c-btn--primary:hover {
  background: var(--color-primary-hover);
}

.c-btn--primary:active {
  background: var(--color-primary-active);
}

.c-btn--secondary {
  background: transparent;
  color: var(--color-primary);
  border: 1px solid var(--color-primary);
}

.c-btn--secondary:hover {
  background: var(--color-primary-subtle);
}

.c-btn--ghost {
  background: transparent;
  color: var(--color-text);
}

.c-btn--ghost:hover {
  background: var(--color-bg);
}

.c-btn--danger {
  background: var(--color-error);
  color: var(--color-text-inverted);
}

.c-btn--danger:hover {
  background: var(--color-error-subtle);
}

/• Размеры */
.c-btn--sm {
  min-height: var(--btn-height-sm);
  padding: var(--btn-padding-sm);
  font-size: var(--btn-font-size-sm);
}

.c-btn--md {
  min-height: var(--btn-height-md);
  padding: var(--btn-padding-md);
  font-size: var(--btn-font-size-md);
}

.c-btn--lg {
  min-height: var(--btn-height-lg);
  padding: var(--btn-padding-lg);
  font-size: var(--btn-font-size-lg);
}

/• Состояния */
.c-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}

.c-btn.is-loading {
  opacity: 0.7;
  cursor: not-allowed;
  pointer-events: none;
}

.c-btn:focus-visible {
  outline: 3px solid var(--color-border-focused);
  outline-offset: 3px;
  box-shadow: 0 0 0 4px color-mix(in oklch, var(--color-primary), white 60%);
}

.c-btn:focus:not(:focus-visible) {
  outline: none;
}

/• Контейнерные запросы */
@container (max-width: 200px) {
  .c-btn {
    min-height: 36px;
    padding: var(--space-xs) var(--space-sm);
    font-size: var(--fs-xs);
  }
}

@layer components;

.c-card {
  container-type: inline-size;
  display: flex;
  flex-direction: column;
  gap: var(--card-gap);
  padding: var(--card-padding);
  border: var(--card-border);
  border-radius: var(--card-radius);
  background: var(--color-surface);
  box-shadow: var(--card-shadow);
  transition:
    box-shadow var(--duration-base) var(--ease-base),
    border-color var(--duration-base) var(--ease-base);
  contain: paint;
}

.c-card--featured {
  border: 2px solid var(--color-primary);
  background: color-mix(in oklch, var(--color-primary), white 95%);
}

.c-card__media {
  aspect-ratio: 16 / 9;
  width: 100%;
  background: var(--color-bg);
  border-radius: var(--radius-md);
  overflow: hidden;
  position: relative;
}

.c-card__img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  display: block;
}

.c-card__badge {
  position: absolute;
  inset-block-start: var(--space-xs);
  inset-inline-start: var(--space-xs);
  font-size: var(--fs-xs);
  font-weight: 600;
  padding: 2px 8px;
  border-radius: var(--radius-full);
  background: var(--color-error);
  color: var(--color-text-inverted);
}

.c-card__body {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  flex: 1;
}

.c-card__title {
  font-size: var(--fs-lg);
  font-weight: 600;
  color: var(--color-text);
  margin: 0;
  line-height: var(--line-height-tight);
}

.c-card__text {
  font-size: var(--fs-sm);
  color: var(--color-text-secondary);
  line-height: var(--line-height-base);
  margin: 0;
}

.c-card__price {
  font-size: var(--fs-xl);
  font-weight: 700;
  color: var(--color-text);
  margin-top: auto;
}

.c-card__footer {
  display: flex;
  gap: var(--space-sm);
  margin-top: auto;
}

@container (max-width: 320px) {
  .c-card {
    padding: var(--space-md);
  }

  .c-card__title {
    font-size: var(--fs-base);
  }
}

@layer components;

.c-modal__overlay {
  position: fixed;
  inset: 0;
  background: var(--modal-backdrop);
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition:
    opacity var(--duration-base) var(--ease-base),
    visibility var(--duration-base);
}

.c-modal__overlay.is-open {
  opacity: 1;
  visibility: visible;
}

.c-modal {
  position: relative;
  width: 90%;
  max-width: var(--modal-max-width);
  padding: var(--modal-padding);
  border-radius: var(--modal-radius);
  background: var(--color-surface);
  color: var(--color-text);
  box-shadow: var(--modal-shadow);
  transform: scale(0.95);
  transition:
    transform var(--duration-base) var(--ease-base),
    opacity var(--duration-base) var(--ease-base);
  opacity: 0;
  visibility: hidden;
  contain: layout paint style;
}

.c-modal__overlay.is-open .c-modal {
  transform: scale(1);
  opacity: 1;
  visibility: visible;
}

.c-modal__close {
  position: absolute;
  inset-block-start: var(--space-sm);
  inset-inline-end: var(--space-sm);
  background: none;
  border: none;
  font-size: var(--fs-lg);
  cursor: pointer;
  color: var(--color-text-muted);
  line-height: 1;
  padding: var(--space-xs);
  border-radius: var(--radius-full);
  transition: background var(--duration-fast), color var(--duration-fast);
}

.c-modal__close:hover {
  background: var(--color-bg);
  color: var(--color-text);
}

.c-modal__close:focus-visible {
  outline: 3px solid var(--color-border-focused);
  outline-offset: 2px;
}

.c-modal__title {
  font-size: var(--fs-2xl);
  font-weight: 600;
  color: var(--color-text);
  margin: 0 0 var(--space-md) 0;
}

.c-modal__body {
  font-size: var(--fs-base);
  line-height: var(--line-height-base);
  color: var(--color-text-secondary);
  margin-bottom: var(--space-xl);
}

.c-modal__actions {
  display: flex;
  gap: var(--space-sm);
  justify-content: flex-end;
}

@media (prefers-reduced-motion: reduce) {
  .c-modal__overlay,
  .c-modal {
    transition-duration: 0.01ms;
    transform: none;
    opacity: 1;
    visibility: visible;
  }
}

// Фокус-ловушка и управление модалкой
class Modal {
  constructor(selector) {
    this.modal = document.querySelector(selector);
    this.overlay = this.modal.querySelector('.c-modal__overlay');
    this.closeBtn = this.modal.querySelector('.c-modal__close');
    this.isOpen = false;
    this.previousFocus = null;

    this.init();
  }

  init() {
    this.closeBtn.addEventListener('click', () => this.close());

    this.overlay.addEventListener('click', (e) => {
      if (e.target === this.overlay) this.close();
    });

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && this.isOpen) this.close();
    });
  }

  open() {
    this.previousFocus = document.activeElement;
    this.isOpen = true;
    this.overlay.classList.add('is-open');
    document.body.style.overflow = 'hidden';

    // Переместить фокус в модалку
    const firstFocusable = this.modal.querySelector(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    );
    if (firstFocusable) firstFocusable.focus();

    this.trapFocus();
  }

  close() {
    this.isOpen = false;
    this.overlay.classList.remove('is-open');
    document.body.style.overflow = '';

    // Вернуть фокус
    if (this.previousFocus) this.previousFocus.focus();
    this.previousFocus = null;
  }

  trapFocus() {
    const focusableElements = this.modal.querySelectorAll(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    );
    const first = focusableElements[0];
    const last = focusableElements[focusableElements.length - 1];

    const handler = (e) => {
      if (!this.isOpen) return;
      if (e.key !== 'Tab') return;

      if (e.shiftKey) {
        if (document.activeElement === first) {
          e.preventDefault();
          last.focus();
        }
      } else {
        if (document.activeElement === last) {
          e.preventDefault();
          first.focus();
        }
      }
    };

    this.modal.addEventListener('keydown', handler);
    this._trapHandler = handler;
  }

  destroy() {
    this.close();
    if (this._trapHandler) {
      this.modal.removeEventListener('keydown', this._trapHandler);
    }
  }
}

@layer components;

.c-nav {
  height: var(--nav-height);
  border-inline-end: 1px solid var(--color-border);
  background: var(--color-surface);
  contain: paint;
}

.c-nav__list {
  display: flex;
  gap: var(--nav-gap);
  padding-inline-start: 0;
  margin: 0;
  list-style: none;
  height: 100%;
  align-items: center;
}

.c-nav__link {
  display: inline-flex;
  align-items: center;
  padding-inline-start: var(--space-sm);
  padding-inline-end: var(--space-sm);
  color: var(--color-text-secondary);
  text-decoration: none;
  font-size: var(--fs-sm);
  font-weight: 500;
  border-radius: var(--radius-md);
  transition: color var(--duration-fast), background var(--duration-fast);
}

.c-nav__link:hover {
  color: var(--color-text);
  background: var(--color-bg);
}

.c-nav__link:focus-visible {
  outline: 3px solid var(--color-border-focused);
  outline-offset: 2px;
  color: var(--color-primary);
  background: color-mix(in oklch, var(--color-primary), white 95%);
}

.c-nav__link[aria-current="page"] {
  color: var(--color-primary);
  font-weight: 600;
}

class NavToggle {
  constructor(toggleSelector, menuSelector) {
    this.toggle = document.querySelector(toggleSelector);
    this.menu = document.querySelector(menuSelector);
    this.isOpen = false;

    this.init();
  }

  init() {
    this.toggle.addEventListener('click', () => this.toggleMenu());

    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && this.isOpen) this.close();
    });
  }

  toggleMenu() {
    if (this.isOpen) this.close();
    else this.open();
  }

  open() {
    this.isOpen = true;
    this.toggle.setAttribute('aria-expanded', 'true');
    this.menu.hidden = false;

    const firstLink = this.menu.querySelector('a');
    if (firstLink) firstLink.focus();
  }

  close() {
    this.isOpen = false;
    this.toggle.setAttribute('aria-expanded', 'false');
    this.menu.hidden = true;
    this.toggle.focus();
  }
}

